package ug.audiocity.studio;
import java.io.IOException;
/** Stereo WSOLA and rate conversion. Streaming output keeps long clips off the Java heap. */
public final class TimeStretch {
 public interface Sink {void sample(float left,float right)throws IOException;}
 static float at(Core.Source s,int frame,int channel){return frame<0||frame>=s.frames()?0:s.sample(frame,channel);}
 public static int resample(Core.Source source,double speed,Sink sink)throws IOException{validate(source,speed);int target=(int)Math.round(source.frames()/speed);for(int i=0;i<target;i++){double pos=i*speed;int a=(int)pos;float t=(float)(pos-a);sink.sample(at(source,a,0)+(at(source,a+1,0)-at(source,a,0))*t,at(source,a,1)+(at(source,a+1,1)-at(source,a,1))*t);}return target;}
 static void validate(Core.Source s,double speed)throws IOException{if(!Double.isFinite(speed)||speed<=0||s.frames()<1||Math.round(s.frames()/speed)<1||s.frames()/speed>Core.MAX_FRAMES)throw new IOException("Retimed source exceeds the 60-minute file limit.");}
 public static int preservePitch(Core.Source source,double speed,Sink sink)throws IOException{validate(source,speed);if(speed<.5||speed>2)throw new IOException("Pitch-preserving tempo changes support 0.5×–2× per change. Use an intermediate tempo or resampling.");if(Math.abs(speed-1)<1e-9){for(int i=0;i<source.frames();i++)sink.sample(source.sample(i,0),source.sample(i,1));return source.frames();}final int hop=1024,search=256;int target=(int)Math.round(source.frames()/speed);float[] tail=new float[hop*2];for(int i=0;i<hop;i++){if(i<target)sink.sample(at(source,i,0),at(source,i,1));tail[2*i]=at(source,i+hop,0);tail[2*i+1]=at(source,i+hop,1);}for(int output=hop;output<target;output+=hop){int expected=(int)Math.round(output*speed),best=expected;double tailEnergy=0;for(int i=0;i<hop;i+=8){double a=tail[2*i]+tail[2*i+1]*.61;tailEnergy+=a*a;}if(tailEnergy>1e-9){double bestScore=-Double.MAX_VALUE;for(int candidate=Math.max(0,expected-search);candidate<=Math.min(source.frames()-1,expected+search);candidate+=4){double dot=0,energy=0;for(int i=0;i<hop;i+=8){double a=tail[2*i]+tail[2*i+1]*.61,b=at(source,candidate+i,0)+at(source,candidate+i,1)*.61;dot+=a*b;energy+=b*b;}double score=dot/Math.sqrt(tailEnergy*energy+1e-20)-Math.abs(candidate-expected)*.000002;if(score>bestScore){bestScore=score;best=candidate;}}}int count=Math.min(hop,target-output);for(int i=0;i<count;i++){float blend=(float)i/hop;float l=tail[2*i]*(1-blend)+at(source,best+i,0)*blend,r=tail[2*i+1]*(1-blend)+at(source,best+i,1)*blend;sink.sample(l,r);}for(int i=0;i<hop;i++){tail[2*i]=at(source,best+hop+i,0);tail[2*i+1]=at(source,best+hop+i,1);}}return target;}
}
